#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> unfinishedTasksAfterShifts(std::vector<int>& incoming, std::vector<int>& capacity) {
        int backlog = 0;
        std::vector<int> res;
        for (size_t i = 0; i < incoming.size(); ++i) {
            backlog = std::max(0, backlog + incoming[i] - capacity[i]);
            res.push_back(backlog);
        }
        return res;
    }
};

class Solution {
    public int[] unfinishedTasksAfterShifts(int[] incoming, int[] capacity) {
        int n = incoming.length;
        int[] res = new int[n];
        int backlog = 0;
        for (int i = 0; i < n; i++) {
            backlog = Math.max(0, backlog + incoming[i] - capacity[i]);
            res[i] = backlog;
        }
        return res;
    }
}

function unfinishedTasksAfterShifts(incoming, capacity) {
    let backlog = 0;
    const res = [];
    for (let i = 0; i < incoming.length; i++) {
        backlog = Math.max(0, backlog + incoming[i] - capacity[i]);
        res.push(backlog);
    }
